            Attr attr = element.getAttributeNodeNS(ns, rightAttr);
            context.report(ISSUE, attr, context.getLocation(attr),
                    "When you define `" + rightAttr + "` you should probably also define `" + leftAttr + "` for right-to-left symmetry");
        }
    }
}
